mod models;

use models::*;

#[tauri::command]
fn ping_rust() -> String {
    format!("Hi! I'm rust, the hardest lang ever")
}

#[tauri::command]
fn get_demo_profile() -> LaunchProfile {
    LaunchProfile {
        name: "My Project".into(),
        description: "Development profile for my web project".into(),
        project_path: Some("C:/Projects/my-app".into()),
        actions: vec![
            LaunchAction {
                id: "1".into(),
                label: "Start Docker".into(),
                enabled: true,
                action_type: ActionType::RunCommand {
                    command: "docker compose up -d".into(),
                    working_dir: Some("C:/Projects/my-app".into()),
                },
            },
            LaunchAction {
                id: "2".into(),
                label: "Run Backend".into(),
                enabled: true,
                action_type: ActionType::RunCommand {
                    command: "npm run dev".into(),
                    working_dir: Some("C:/Projects/my-app/backend".into()),
                },
            },
            LaunchAction {
                id: "3".into(),
                label: "Open Swagger".into(),
                enabled: true,
                action_type: ActionType::OpenUrl {
                    url: "http://localhost:3000/swagger".into(),
                },
            },
        ],
    }
}

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    tauri::Builder::default()
        .plugin(tauri_plugin_dialog::init())
        .plugin(tauri_plugin_opener::init())
        .invoke_handler(tauri::generate_handler![ping_rust, get_demo_profile])
        .run(tauri::generate_context!())
        .expect("error while running tauri application");
}

