/// Простейшая реализация LaunchEngine.
///
/// Пока просто логирует действие и возвращает Success.
/// В будущем здесь будет запуск процессов, открытие URL и т.д.
pub struct SimpleLaunchEngine;

impl LaunchEngine for SimpleLaunchEngine {
    fn execute_action(&self, action: &LaunchAction) -> Result<ActionStatus, String> {
        if !action.enabled {
            return Ok(ActionStatus::Skipped {
                reason: format!("Action '{}' is disabled", action.label),
            });
        }

        match &action.action_type {
            ActionType::RunCommand { command, working_dir } => {
                println!("[LaunchEngine] Would run: '{}' in {:?}", command, working_dir);
                Ok(ActionStatus::Success {
                    message: format!("Command queued: {}", command),
                })
            }
            ActionType::OpenUrl { url } => {
                println!("[LaunchEngine] Would open URL: {}", url);
                Ok(ActionStatus::Success {
                    message: format!("Opening URL: {}", url),
                })
            }
            ActionType::Delay { seconds } => {
                println!("[LaunchEngine] Would wait: {}s", seconds);
                Ok(ActionStatus::Success {
                    message: format!("Delayed {}s", seconds),
                })
            }
            _ => Ok(ActionStatus::Success {
                message: format!("Simulated: {}", action.label),
            }),
        }
    }
}
