    if ("OpenUrl" in actionType) return actionType.OpenUrl.url;
    if ("OpenApplication" in actionType) return actionType.OpenApplication.path;
    if ("WaitForUrl" in actionType) return `⏳ ${actionType.WaitForUrl.url}`;
    if ("WaitForPort" in actionType) return `⏳ ${actionType.WaitForPort.host}:${actionType.WaitForPort.port}`;
    if ("Delay" in actionType) return `⏱ ${actionType.Delay.seconds}s`;
    if ("ExecuteScript" in actionType) return `▶ ${actionType.ExecuteScript.script}`;
    return "?";
  }
</script>

