// ============================================================
// Модели данных DevLauncher
//
// Все структуры данных, которыми обмениваются фронтенд и бэкенд.
// Сериализация/десериализация JSON — через serde.
// ============================================================

use serde::{Deserialize, Serialize};

// --------------------------------------------------
// ActionType — тип действия в профиле запуска.
//
// Rust-перечисление (enum). В JSON превращается в:
//   {"RunCommand": {"command": "...", "working_dir": null}}
// --------------------------------------------------
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum ActionType {
    /// Запустить команду в терминале
    RunCommand {
        command: String,
        working_dir: Option<String>,
    },
    /// Открыть приложение (VS Code, браузер и т.д.)
    OpenApplication {
        path: String,
        args: Option<String>,
    },
    /// Открыть URL в браузере
    OpenUrl {
        url: String,
    },
    /// Ждать, пока URL станет доступен (HTTP GET)
    WaitForUrl {
        url: String,
        timeout_secs: u64,
    },
    /// Ждать, пока TCP-порт откроется
    WaitForPort {
        host: String,
        port: u16,
        timeout_secs: u64,
    },
    /// Подождать указанное количество секунд
    Delay {
        seconds: u64,
    },
    /// Выполнить произвольный скрипт
    ExecuteScript {
        script: String,
        shell: Option<String>,
    },
}

// --------------------------------------------------
// LaunchAction — одно действие в профиле.
//
// У каждого действия есть:
//   • id      — уникальный идентификатор
//   • label   — человекочитаемое название
//   • enabled — включено/выключено
//   • action_type — что именно делать
// --------------------------------------------------
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct LaunchAction {
    pub id: String,
    pub label: String,
    pub enabled: bool,
    pub action_type: ActionType,
}

// --------------------------------------------------
// LaunchProfile — профиль запуска проекта.
//
// Упорядоченный список действий для запуска проекта.
// Сохраняется в JSON-файл.
// --------------------------------------------------
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct LaunchProfile {
    pub name: String,
    pub description: String,
    pub project_path: Option<String>,
    pub actions: Vec<LaunchAction>,
}

// --------------------------------------------------
// ActionStatus — результат выполнения одного действия.
//
// Возвращается из LaunchEngine на фронтенд.
// --------------------------------------------------
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum ActionStatus {
    Success {
        message: String,
    },
    Failed {
        error: String,
    },
    Skipped {
        reason: String,
    },
}

// ============================================================
// ProfileManager — управление профилями запуска.
//
// # Архитектура
//
// ProfileManager — это трейт (интерфейс). Любая реализация
// этого трейта может быть подставлена в приложение. Это
// позволяет легко:
//   • переключаться между разными способами хранения
//   • писать тесты с mock-реализациями
//
// JsonProfileManager — конкретная реализация, хранящая
// профили как JSON-файлы в指定нной папке.
// ============================================================

use std::path::{Path, PathBuf};
use std::fs;

use crate::models::*;

// --------------------------------------------------
// Трейт ProfileManager
// --------------------------------------------------
pub trait ProfileManager: Send + Sync {
    /// Вернуть список всех сохранённых профилей
    fn list_profiles(&self) -> Result<Vec<LaunchProfile>, String>;

    /// Вернуть профиль по имени
    fn get_profile(&self, name: &str) -> Result<LaunchProfile, String>;

    /// Сохранить профиль (создать или перезаписать)
    fn save_profile(&self, profile: &LaunchProfile) -> Result<(), String>;

    /// Удалить профиль по имени
    fn delete_profile(&self, name: &str) -> Result<(), String>;
}

// --------------------------------------------------
// JsonProfileManager — профили в JSON-файлах
//
// Каждый профиль = отдельный .json файл.
// Имя файла = имя профиля + ".json"
// --------------------------------------------------
pub struct JsonProfileManager {
    profiles_dir: PathBuf,
}

impl JsonProfileManager {
    pub fn new(profiles_dir: PathBuf) -> Self {
        Self { profiles_dir }
    }

    /// Построить путь к файлу профиля
    fn profile_path(&self, name: &str) -> PathBuf {
        self.profiles_dir.join(format!("{}.json", name))
    }
}

impl ProfileManager for JsonProfileManager {
    fn list_profiles(&self) -> Result<Vec<LaunchProfile>, String> {
        let mut profiles = Vec::new();

        // Читаем содержимое папки профилей
        let entries = fs::read_dir(&self.profiles_dir)
            .map_err(|e| format!("Не удалось прочитать папку профилей: {}", e))?;

        for entry in entries {
            let entry = entry.map_err(|e| format!("Ошибка чтения записи: {}", e))?;
            let path = entry.path();

            // Нас интересуют только .json файлы
            if path.extension().map_or(false, |ext| ext == "json") {
                let content = fs::read_to_string(&path)
                    .map_err(|e| format!("Не удалось прочитать {}: {}", path.display(), e))?;
                let profile: LaunchProfile = serde_json::from_str(&content)
                    .map_err(|e| format!("Ошибка парсинга {}: {}", path.display(), e))?;
                profiles.push(profile);
            }
        }

        Ok(profiles)
    }

    fn get_profile(&self, name: &str) -> Result<LaunchProfile, String> {
        let path = self.profile_path(name);
        let content = fs::read_to_string(&path)
            .map_err(|e| format!("Не удалось прочитать профиль '{}': {}", name, e))?;
        serde_json::from_str(&content)
            .map_err(|e| format!("Ошибка парсинга профиля '{}': {}", name, e))
    }

    fn save_profile(&self, profile: &LaunchProfile) -> Result<(), String> {
        let path = self.profile_path(&profile.name);
        let content = serde_json::to_string_pretty(profile)
            .map_err(|e| format!("Ошибка сериализации профиля: {}", e))?;
        fs::write(&path, content)
            .map_err(|e| format!("Не удалось записать профиль '{}': {}", profile.name, e))
    }

    fn delete_profile(&self, name: &str) -> Result<(), String> {
        let path = self.profile_path(name);
        fs::remove_file(&path)
            .map_err(|e| format!("Не удалось удалить профиль '{}': {}", name, e))
    }
}

// ============================================================
// LaunchEngine — движок запуска профилей.
//
// LaunchEngine выполняет действия из LaunchProfile одно за другим.
// Он НЕ анализирует проекты — только исполняет.
//
// В этой версии — заглушка. Команды просто логируются.
// Полноценная реализация будет позже и будет:
//   • запускать процессы в терминале
//   • открывать URL и приложения
//   • ждать порты/URL
//   • обрабатывать ошибки и таймауты
// ============================================================

use crate::models::*;

// --------------------------------------------------
// Трейт LaunchEngine
// --------------------------------------------------
pub trait LaunchEngine: Send + Sync {
    /// Выполнить одно действие и вернуть результат
    fn execute_action(&self, action: &LaunchAction) -> Result<ActionStatus, String>;
}

// --------------------------------------------------
// SimpleLaunchEngine — заглушка
//
// Пока просто пишет в консоль и возвращает Success.
// Это позволяет разрабатывать UI до реализации движка.
// --------------------------------------------------
pub struct SimpleLaunchEngine;

impl LaunchEngine for SimpleLaunchEngine {
    fn execute_action(&self, action: &LaunchAction) -> Result<ActionStatus, String> {
        // Если действие выключено — пропускаем
        if !action.enabled {
            return Ok(ActionStatus::Skipped {
                reason: format!("Действие '{}' отключено", action.label),
            });
        }

        // Логируем и возвращаем заглушку
        match &action.action_type {
            ActionType::RunCommand { command, working_dir } => {
                println!(
                    "[LaunchEngine] Команда: '{}' в папке {:?}",
                    command, working_dir
                );
                Ok(ActionStatus::Success {
                    message: format!("[Заглушка] Команда запущена: {}", command),
                })
            }
            ActionType::OpenUrl { url } => {
                println!("[LaunchEngine] Открыть URL: {}", url);
                Ok(ActionStatus::Success {
                    message: format!("[Заглушка] Открыт URL: {}", url),
                })
            }
            ActionType::OpenApplication { path, args } => {
                println!("[LaunchEngine] Запустить: {} {:?}", path, args);
                Ok(ActionStatus::Success {
                    message: format!("[Заглушка] Запущено: {}", path),
                })
            }
            ActionType::WaitForUrl { url, timeout_secs } => {
                println!("[LaunchEngine] Жду URL {} ({}s)", url, timeout_secs);
                Ok(ActionStatus::Success {
                    message: format!("[Заглушка] URL доступен: {}", url),
                })
            }
            ActionType::WaitForPort { host, port, timeout_secs } => {
                println!("[LaunchEngine] Жду порт {}:{} ({}s)", host, port, timeout_secs);
                Ok(ActionStatus::Success {
                    message: format!("[Заглушка] Порт доступен: {}:{}", host, port),
                })
            }
            ActionType::Delay { seconds } => {
                println!("[LaunchEngine] Пауза {}s", seconds);
                Ok(ActionStatus::Success {
                    message: format!("[Заглушка] Пауза {} секунд", seconds),
                })
            }
            ActionType::ExecuteScript { script, shell } => {
                println!("[LaunchEngine] Скрипт: '{}' через {:?}", script, shell);
                Ok(ActionStatus::Success {
                    message: format!("[Заглушка] Скрипт выполнен: {}", script),
                })
            }
        }
    }
}

// ============================================================
// ProjectAnalyzer — анализатор проектов.
//
// Анализатор изучает структуру папки проекта и предлагает
// LaunchProfile с предполагаемыми действиями.
//
// ВАЖНО: Анализатор НИКОГДА не запускает действия.
// Он только читает файлы и возвращает предложение.
//
// Текущая реализация — заглушка, всегда возвращает
// одинаковый профиль. Полная версия будет искать:
//   • docker-compose.yml → Start Docker
//   • package.json → Run npm dev
//   • Cargo.toml → Run cargo
//   • swagger/ → Open Swagger URL
// и т.д.
// ============================================================

use crate::models::*;

// --------------------------------------------------
// Трейт ProjectAnalyzer
// --------------------------------------------------
pub trait ProjectAnalyzer: Send + Sync {
    /// Проанализировать проект и предложить профиль
    fn analyze(&self, project_path: &str) -> Result<LaunchProfile, String>;
}

// --------------------------------------------------
// SimpleAnalyzer — заглушка
//
// Возвращает пример профиля с одним действием.
// --------------------------------------------------
pub struct SimpleAnalyzer;

impl ProjectAnalyzer for SimpleAnalyzer {
    fn analyze(&self, project_path: &str) -> Result<LaunchProfile, String> {
        // TODO: настоящий анализ проекта
        Ok(LaunchProfile {
            name: "проанализированный проект".into(),
            description: format!("Автоматически найденный профиль для {}", project_path),
            project_path: Some(project_path.to_string()),
            actions: vec![
                LaunchAction {
                    id: "act_1".into(),
                    label: "Запустить Docker".into(),
                    enabled: true,
                    action_type: ActionType::RunCommand {
                        command: "docker compose up -d".into(),
                        working_dir: Some(project_path.to_string()),
                    },
                },
                LaunchAction {
                    id: "act_2".into(),
                    label: "Открыть проект в VS Code".into(),
                    enabled: true,
                    action_type: ActionType::OpenApplication {
                        path: "code".into(),
                        args: Some(project_path.to_string()),
                    },
                },
            ],
        })
    }
}

