// ============================================================
// Tauri-команды приложения.
//
// Каждая команда — тонкая обёртка: получает состояние (State),
// вызывает метод нужного модуля, возвращает результат.
//
// Команды НЕ содержат бизнес-логики.
// Вся логика — в модулях (profile_manager, launch_engine, analyzer).
// ============================================================

use std::sync::Arc;
use tauri::State;

use crate::models::*;
use crate::profile_manager::ProfileManager;
use crate::launch_engine::LaunchEngine;
use crate::analyzer::ProjectAnalyzer;

// --------------------------------------------------
// AppState — глобальное состояние приложения.
//
// Tauri внедряет его в команды через State<'_, AppState>.
// Arc<dyn Trait> позволяет подменять реализации
// (например, для тестов или разных платформ).
// --------------------------------------------------
pub struct AppState {
    pub profile_manager: Arc<dyn ProfileManager>,
    pub launch_engine: Arc<dyn LaunchEngine>,
    pub analyzer: Arc<dyn ProjectAnalyzer>,
}

// ===== Системные команды =====

/// Проверка связи с Rust-бэкендом
#[tauri::command]
pub fn ping_rust() -> String {
    "pong".into()
}

/// Получить демо-профиль (для ознакомления с UI)
#[tauri::command]
pub fn get_demo_profile() -> LaunchProfile {
    LaunchProfile {
        name: "демо-проект".into(),
        description: "Пример профиля для веб-разработки".into(),
        project_path: None,
        actions: vec![
            LaunchAction {
                id: generate_id(),
                label: "Запустить Docker".into(),
                enabled: true,
                action_type: ActionType::RunCommand {
                    command: "docker compose up -d".into(),
                    working_dir: None,
                },
            },
            LaunchAction {
                id: generate_id(),
                label: "Запустить бэкенд".into(),
                enabled: true,
                action_type: ActionType::RunCommand {
                    command: "npm run dev".into(),
                    working_dir: Some("./backend".into()),
                },
            },
            LaunchAction {
                id: generate_id(),
                label: "Открыть Swagger".into(),
                enabled: true,
                action_type: ActionType::OpenUrl {
                    url: "http://localhost:3000/swagger".into(),
                },
            },
        ],
    }
}

/// Генерация простого ID на основе времени
fn generate_id() -> String {
    use std::time::{SystemTime, UNIX_EPOCH};
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos();
    format!("act_{}", nanos)
}

// ===== ProfileManager команды =====

/// Получить список всех сохранённых профилей
#[tauri::command]
pub fn list_profiles(state: State<'_, AppState>) -> Result<Vec<LaunchProfile>, String> {
    state.profile_manager.list_profiles()
}

/// Получить один профиль по имени
#[tauri::command]
pub fn get_profile(state: State<'_, AppState>, name: String) -> Result<LaunchProfile, String> {
    state.profile_manager.get_profile(&name)
}

/// Сохранить профиль (создать или перезаписать)
#[tauri::command]
pub fn save_profile(state: State<'_, AppState>, profile: LaunchProfile) -> Result<(), String> {
    state.profile_manager.save_profile(&profile)
}

/// Удалить профиль по имени
#[tauri::command]
pub fn delete_profile(state: State<'_, AppState>, name: String) -> Result<(), String> {
    state.profile_manager.delete_profile(&name)
}

// ===== LaunchEngine команды =====

/// Выполнить одно действие
#[tauri::command]
pub fn execute_action(
    state: State<'_, AppState>,
    action: LaunchAction,
) -> Result<ActionStatus, String> {
    state.launch_engine.execute_action(&action)
}

// ===== Analyzer команды =====

/// Проанализировать проект и получить предложенный профиль
#[tauri::command]
pub fn analyze_project(
    state: State<'_, AppState>,
    path: String,
) -> Result<LaunchProfile, String> {
    state.analyzer.analyze(&path)
}

// ============================================================
// Точка сборки приложения DevLauncher.
//
// Здесь происходит "сборка" (wiring):
//   1. Объявляем модули (каждый в своём файле)
//   2. В setup() создаём экземпляры модулей
//   3. Регистрируем состояние (State) и команды
//   4. Запускаем Tauri
//
// Это единственное место, где все модули соединяются.
// Каждый модуль ничего не знает о других модулях.
// ============================================================

mod models;
mod profile_manager;
mod launch_engine;
mod analyzer;
mod commands;

use std::sync::Arc;
use commands::AppState;

#[cfg_attr(mobile, tauri::mobile_entry_point)]
pub fn run() {
    tauri::Builder::default()
        // --- Плагины ---
        .plugin(tauri_plugin_dialog::init())
        .plugin(tauri_plugin_opener::init())

        // --- Настройка приложения ---
        .setup(|app| {
            // Получаем стандартную папку для данных приложения
            let data_dir = app
                .path()
                .app_data_dir()
                .expect("Не удалось получить папку данных приложения");

            // Папка для JSON-файлов профилей
            let profiles_dir = data_dir.join("profiles");

            // Создаём папку, если её нет
            std::fs::create_dir_all(&profiles_dir)
                .expect("Не удалось создать папку профилей");

            // Создаём состояние приложения с реальными реализациями
            let app_state = AppState {
                profile_manager: Arc::new(
                    profile_manager::JsonProfileManager::new(profiles_dir),
                ),
                launch_engine: Arc::new(launch_engine::SimpleLaunchEngine),
                analyzer: Arc::new(analyzer::SimpleAnalyzer),
            };

            // Регистрируем состояние — оно будет доступно
            // во всех командах через State<'_, AppState>
            app.manage(app_state);

            Ok(())
        })

        // --- Команды ---
        .invoke_handler(tauri::generate_handler![
            commands::ping_rust,
            commands::get_demo_profile,
            commands::list_profiles,
            commands::get_profile,
            commands::save_profile,
            commands::delete_profile,
            commands::execute_action,
            commands::analyze_project,
        ])

        // --- Запуск ---
        .run(tauri::generate_context!())
        .expect("Ошибка при запуске Tauri приложения");
}

// ============================================================
// Типы данных DevLauncher (TypeScript)
//
// Эти типы должны совпадать с Rust-структурами из models.rs.
// Tauri автоматически преобразует JSON, поэтому структура
// данных на фронтенде и бэкенде должна быть одинаковой.
//
// Rust-перечисление (enum) в JSON выглядит так:
//   {"VariantName": {field1: value1, field2: value2}}
// TypeScript-аналог — discriminated union (объединение типов).
// ============================================================

// ---- ActionType ----

export type RunCommand = {
  command: string;
  working_dir: string | null;
};

export type OpenApplication = {
  path: string;
  args: string | null;
};

export type OpenUrl = {
  url: string;
};

export type WaitForUrl = {
  url: string;
  timeout_secs: number;
};

export type WaitForPort = {
  host: string;
  port: number;
  timeout_secs: number;
};

export type Delay = {
  seconds: number;
};

export type ExecuteScript = {
  script: string;
  shell: string | null;
};

// Объединение всех вариантов ActionType.
// Внимание: ключ объекта — это название варианта из Rust.
export type ActionType =
  | { RunCommand: RunCommand }
  | { OpenApplication: OpenApplication }
  | { OpenUrl: OpenUrl }
  | { WaitForUrl: WaitForUrl }
  | { WaitForPort: WaitForPort }
  | { Delay: Delay }
  | { ExecuteScript: ExecuteScript };

// ---- LaunchAction ----

export type LaunchAction = {
  id: string;
  label: string;
  enabled: boolean;
  action_type: ActionType;
};

// ---- LaunchProfile ----

export type LaunchProfile = {
  name: string;
  description: string;
  project_path: string | null;
  actions: LaunchAction[];
};

// ---- ActionStatus ----

export type ActionStatus =
  | { Success: { message: string } }
  | { Failed: { error: string } }
  | { Skipped: { reason: string } };

// ============================================================
// API-слой для вызова Rust-команд.
//
// Все вызовы `invoke()` собраны здесь, чтобы страницы
// (svelte-компоненты) не зависели от @tauri-apps/api/core
// напрямую.
//
// Каждая функция:
//   • принимает типизированные параметры
//   • вызывает Rust-команду через invoke()
//   • возвращает Promise с типизированным результатом
// ============================================================

import { invoke } from "@tauri-apps/api/core";
import type { LaunchProfile, LaunchAction, ActionStatus } from "./types";

// ===== Системные =====

/** Проверить связь с Rust-бэкендом */
export async function ping(): Promise<string> {
  return invoke("ping_rust");
}

/** Получить демо-профиль для ознакомления */
export async function getDemoProfile(): Promise<LaunchProfile> {
  return invoke("get_demo_profile");
}

// ===== ProfileManager =====

/** Получить список сохранённых профилей */
export async function listProfiles(): Promise<LaunchProfile[]> {
  return invoke("list_profiles");
}

/** Получить профиль по имени */
export async function getProfile(name: string): Promise<LaunchProfile> {
  return invoke("get_profile", { name });
}

/** Сохранить профиль (создать или перезаписать) */
export async function saveProfile(profile: LaunchProfile): Promise<void> {
  return invoke("save_profile", { profile });
}

/** Удалить профиль по имени */
export async function deleteProfile(name: string): Promise<void> {
  return invoke("delete_profile", { name });
}

// ===== LaunchEngine =====

/** Выполнить одно действие */
export async function executeAction(action: LaunchAction): Promise<ActionStatus> {
  return invoke("execute_action", { action });
}

// ===== Analyzer =====

/** Проанализировать папку проекта и получить предложенный профиль */
export async function analyzeProject(path: string): Promise<LaunchProfile> {
  return invoke("analyze_project", { path });
}

