display.text:
// ============================================================
// LaunchEngine — движок запуска профилей.
//
// LaunchEngine выполняет действия из LaunchProfile одно за другим.
// Он НЕ анализирует проекты — только исполняет.
use std::time::Duration;
use std::process::Command;
use std::thread;
use std::net::{TcpStream, ToSocketAddrs};
use std::io::{Write, BufReader, BufRead};


use crate::models::*;

// --------------------------------------------------
// Трейт LaunchEngine
// --------------------------------------------------
pub trait LaunchEngine: Send + Sync {
    /// Выполнить одно действие и вернуть результат
    fn execute_action(&self, action: &LaunchAction) -> Result<ActionStatus, String>;
}


pub struct ProcessLaunchEngine;

impl LaunchEngine for ProcessLaunchEngine {
    fn execute_action(&self, action: &LaunchAction) -> Result<ActionStatus, String> {
        // Если действие выключено — пропускаем
        if !action.enabled {
            return Ok(ActionStatus::Skipped {
                reason: format!("Действие '{}' отключено", action.label),
            });
        }

        match &action.action_type {
            ActionType::RunCommand { command, working_dir } => {
                println!(
                    "[LaunchEngine] Команда: '{}' в папке {:?}",
                    command, working_dir
                );
                let mut proccess_command = Command::new("cmd");
                proccess_command.arg("/C").arg(command);

                if let Some(dir) = working_dir {
                    proccess_command.current_dir(dir);
                }

                match proccess_command.spawn() {
                    Ok(_) => {
                            Ok(ActionStatus::Success {
                                message: format!("Команда успешно запущена в фоне: {}", command),
                            })
                    }
                    Err(err) => {
                        Err(format!("Ошибка запуска процесса: {}", err))
                    }
                }
            }
            ActionType::OpenUrl { url } => {
                println!("[LaunchEngine] Открыть URL: {:?}", url);

                    match webbrowser::open(url) {
                      Ok(_) => {
                        Ok(ActionStatus::Success {
                    message: format!("Открыт URL: {}", url),
                }) 
                    }
                    Err(err) => {
                        Err(format!("Ошибка открытия браузера: {}", err))
                    }
                }
            }
            ActionType::OpenApplication { path, args } => {
                println!("[LaunchEngine] Запустить: {} {:?}", path, args);
                let mut proccess_command = Command::new(path);
                if let Some(args_str) = args {
                    proccess_command.args(args_str.split_whitespace());
                }

                match proccess_command.spawn() {
                    Ok(_) => {
                            Ok(ActionStatus::Success {
                                message: format!("Приложение успешно запущено в фоне"),
                            })
                    }
                    Err(err) => {
                        Err(format!("Ошибка запуска приложения: {}", err))
                    }
                }
            }
            ActionType::WaitForUrl { url, timeout_secs } => {
                println!("[LaunchEngine] Жду URL {} ({}s)", url, timeout_secs);

                let pre_formatted_url = url.replace("http://", "").replace("https://", "");
                let formatted_url = pre_formatted_url.split('/').next().unwrap_or(pre_formatted_url.as_str());

                if let Ok(mut addrs) = formatted_url.to_socket_addrs() {
                    if let Some(addr) = addrs.next() {

                        for _ in 0..*timeout_secs {
                            match TcpStream::connect_timeout(&addr, Duration::from_secs(2)) {
                                Ok(mut stream) => {
                                    // Исправлено: Строка запроса БЕЗ отступов слева и с макросом format!
                                    let req = format!(
"GET / HTTP/1.1\r
Host: {}\r
Connection: close\r
\r\n", formatted_url);

                                    // Отправляем запрос. Если не ушло — игнорируем ошибку и идем на следующий круг
                                    if stream.write_all(req.as_bytes()).is_err() {
                                        thread::sleep(Duration::from_secs(1));
                                        continue;
                                    }

                                    let mut reader = BufReader::new(&stream);
                                    let mut response_line = String::new();

                                    // Читаем ответ. Если не прочиталось — на следующий круг
                                    if reader.read_line(&mut response_line).is_err() {
                                        thread::sleep(Duration::from_secs(1));
                                        continue;
                                    }                  

                                    let split_resp_parts: Vec<&str> = response_line.split_whitespace().collect();

                                    // Исправлено: Безопасное извлечение статус-кода через .get(1)
                                    if let Some(status_code) = split_resp_parts.get(1) {
                                        // Проверяем, начинается ли статус с 2xx или 3xx
                                        if status_code.starts_with('2') || status_code.starts_with('3') {
                                            // Используем return, чтобы выйти из ВСЕЙ функции движка
                                            return Ok(ActionStatus::Success { 
                                                message: format!("URL {} успешно ответил со статусом {}", url, status_code)
                                            });
                                        } else {
                                            println!("[LaunchEngine] Сервер {} вернул плохой статус: {}", url, status_code);
                                        }
                                    }
                                }
                                Err(err) => {
                                    println!("[LaunchEngine] Ошибка соединения с {}: {}. Повторяю...", url, err);
                                }
                            }

                            // Делаем паузу в 1 секунду между попытками подключения
                            thread::sleep(Duration::from_secs(1));
                        }
                    }
                }

                // Если мы вывалились из цикла, значит время вышло, а сервер так и не ответил добром
                Err(format!("Не удалось получить успешный ответ от {} за {} секунд", url, timeout_secs))
            }



            ActionType::WaitForPort { host, port, timeout_secs } => {
                println!("[LaunchEngine] Жду порт {}:{} ({}s)", host, port, timeout_secs);

                let addr_str = format!("{}:{}", host, port);

                if let Ok(mut addrs) = addr_str.to_socket_addrs() {
                    if let Some(addr) = addrs.next() {

                       for _ in 0..*timeout_secs {
                        match TcpStream::connect_timeout(&addr,Duration::from_secs(1)) {
                            Ok(_) => {
                                return Ok(ActionStatus::Success { 
                            message: format!("Успех! Соединение установлено с {}:{}", host, port)
                        });
                            }
                            Err(_) => {
                                println!("[LaunchEngine] Порт {}:{} еще не доступен, проверяю снова...", host, port);

                            }
                        }
                        }
                    }
                }
                Err(format!("Не удалось подключиться к порту {}:{} после {} секунд ожидания", host, port, timeout_secs))

            }
            ActionType::Delay { seconds } => {
                println!("[LaunchEngine] Пауза {}s", seconds);
                let dur = Duration::from_secs(*seconds);
                thread::sleep(dur);
                Ok(ActionStatus::Success {
                    message: format!("Пауза {} секунд", seconds),
                })
            }
            ActionType::ExecuteScript { script, shell } => {
                println!("[LaunchEngine] Скрипт: '{}' через {:?}", script, shell);
                let shell_name = shell.as_deref().unwrap_or("cmd");
                let flag = match shell_name {
                    "cmd" => "/C",
                    "powershell" | "pwsh" => "-Command",
                    _ => "-c",
                };

                let mut command = Command::new(shell_name);
                command.args([flag, script]);


                match command.status() {
                    Ok(exit_status) => {
                        if exit_status.success() {
                          Ok(ActionStatus::Success {
                                message: format!("Скрипт успешно выполнен через {}: {}", shell_name, script),
                            })  
                        } else {
                            let code = exit_status.code().unwrap_or(-1);
                            Ok(ActionStatus::Failed { 
                                error: format!("Скрипт завершился с ошибкой (код: {})", code) 
                            })
                        }

                    }
                    Err(err) => {
            Err(format!("Не удалось запустить оболочку {}: {}", shell_name, err))
        }
                }
            }
        }
    }
}

