display.text:
// ============================================================
// ProjectAnalyzer — анализатор проектов.
//
// Анализатор изучает структуру папки проекта и предлагает
// LaunchProfile с предполагаемыми действиями.
//
// ВАЖНО: Анализатор НИКОГДА не запускает действия.
// Он только читает файлы и возвращает предложение.
// ============================================================
use std::fs;
use walkdir::WalkDir;
use toml;
use std::path::Path;

use crate::models::*;


// --------------------------------------------------
// Трейт ProjectAnalyzer
// --------------------------------------------------
pub trait ProjectAnalyzer: Send + Sync {
    /// Проанализировать проект и предложить профиль
    fn analyze(&self, project_path: &str) -> Result<LaunchProfile, String>;
}

pub struct FsProjectAnalyzer;

impl ProjectAnalyzer for FsProjectAnalyzer {
    fn analyze(&self, project_path: &str) -> Result<LaunchProfile, String> {

        let mut launch_actions: Vec<LaunchAction> = Vec::new();
        let walker = WalkDir::new(project_path).follow_links(false).into_iter();
        let mut it = walker;

        let mut has_index_html = false;
        let index_html_sys_path = String::new();
        let mut has_docker = false;
        let mut is_python_project = false;

        while let Some(entry_result) = it.next() {
            let entry = match entry_result {
                Ok(e) => e,
                Err(err) => {
                    println!("[ProjectAnalyzer] Ошибка доступа к элементу: {}", err);
                    continue;
                }            
            };

            let path = entry.path();
            let filename = path.file_name().and_then(|n| n.to_str()).unwrap_or("");

            if entry.file_type().is_dir() {
                if filename == "node_modules" || filename == ".git" || filename == "target" || filename == ".venv" {
                    it.skip_current_dir(); // Говорим walkdir вообще НЕ заходить внутрь этой папки
                    continue;
                }
            }

            let current_working_dir = path.parent()
                .and_then(|p| p.to_str())
                .unwrap_or(project_path);



            match filename {
                "docker-compose.yml" | "docker_compose.yaml" => {
                    let action = LaunchAction {
                        id: generate_id(),
                        label: "Запустить Docker".into(),
                        enabled: true,
                        action_type: ActionType::RunCommand { 
                            command: "docker compose up -d".into(), 
                            working_dir: Some(current_working_dir.to_string()) 
                        },
                    };
                    launch_actions.push(action);
                    has_docker = true; // Если докер есть, то на некоторые действия ставится enable = false, но пользователь сможет сменить enable в просмотре профиля
                }
                "package.json" => {
                    let content = fs::read_to_string(&path).map_err(|e| format!("Ошибка чтения: {}", e))?;
                    let value: serde_json::Value = serde_json::from_str(&content)
                        .map_err(|e| format!("Ошибка парсинга package.json: {}", e))?;

                    let scripts = value.get("scripts");
                    let dependencies = value.get("dependencies");
                    let dev_dependencies = value.get("devDependencies");

                    let has_dep = |pkg: &str| {
                        dependencies.and_then(|d| d.get(pkg)).is_some() || 
                        dev_dependencies.and_then(|d| d.get(pkg)).is_some()
                    };

                    let run_command = if has_dep("expo") {
                        // Если это Expo-проект
                        "npx expo start".to_string()
                    } else if has_dep("@nestjs/core") {
                        // Если это NestJS
                        scripts.and_then(|s| s.get("start:dev"))
                            .and_then(|c| c.as_str())
                            .unwrap_or("npm run start:dev")
                            .to_string()
                    } else {
                        // Для всех остальных проектов (Next.js, Vite, Nuxt, React)
                        let chosen_script = scripts.and_then(|s| s.get("dev").or_else(|| s.get("start")))
                                                .and_then(|c| c.as_str())
                                                .unwrap_or("dev");

                        format!("npm run {}", chosen_script)
                    };

                    // Создаем действие запуска для этого JS-проекта
                    let js_action = LaunchAction {
                        id: generate_id(),
                        label: format!("Запустить Node.js проект ({})", run_command),
                        enabled: true,
                        action_type: ActionType::RunCommand {
                            command: run_command,
                            working_dir: Some(current_working_dir.to_string()),
                        },
                    };

                    // Добавляем созданное действие в твой вектор launch_actions
                    launch_actions.push(js_action);

                    if !has_dep("expo") {
                        let port_action = LaunchAction {
                            id: generate_id(),
                            label: "Ожидание веб-порта для js".into(),
                            enabled: true,
                            action_type: ActionType::WaitForPort {
                                host: "127.0.0.1".into(),
                                port: 3000, // Ставим 3000 как самый частый дефолт
                                timeout_secs: 30,
                            },
                        };
                        launch_actions.push(port_action);
                    }
                }
                "Cargo.toml" => {
                    let content = fs::read_to_string(&path).map_err(|e| format!("Ошибка чтения: {}", e))?;
                    let value: toml::Value = toml::from_str(&content).map_err(|e| format!("Ошибка парсинга Cargo.toml: {}", e))?;
                    // Проверяем, является ли этот файл просто корнем Workspace
                    let is_workspace = value.get("workspace").is_some();

                    if is_workspace {
                        // Если это виртуальное рабочее пространство, сам по себе он не запускается.
                        // Мы его пропускаем, так как walkdir все равно зайдет в подпапки и найдет там отдельные Cargo.toml проектов
                        continue;
                    }
                    let has_tauri = value.get("dependencies")
                        .and_then(|d| d.get("tauri"))
                        .is_some();

                    let rust_command = if has_tauri {
                        "cargo tauri dev"
                    } else {
                        "cargo run"
                    };

                    let cargo_action = LaunchAction {
                        id: generate_id(),
                        label: format!("Запустить Rust ({})", rust_command).into(),
                        enabled: true,
                        action_type: ActionType::RunCommand {
                            command: rust_command.into(),
                            working_dir: Some(current_working_dir.to_string()),
                        },
                    };
                    launch_actions.push(cargo_action);



                }
                "main.go" => {
                    let go_action = LaunchAction {
                        id: generate_id(),
                        label: "Запустить Go".into(),
                        enabled: !has_docker,
                        action_type: ActionType::RunCommand {
                            command: "go run .".into(), 
                            working_dir: Some(current_working_dir.to_string())
                        }
                    };
                    launch_actions.push(go_action)
                }
                "requirements.txt" => {
                    let py_action1 = LaunchAction {
                        id: generate_id(),
                        label: "Установка зависимостей из requirements.txt".into(),
                        enabled: !has_docker,
                        action_type: ActionType::RunCommand {
                            command: "pip install -r requirements.txt".into(), 
                            working_dir: Some(current_working_dir.to_string())
                            }
                    };
                    launch_actions.push(py_action1);
                    is_python_project = true;
                }    
                "main.py" => {
                    let py_action2 = LaunchAction {
                        id: generate_id(),
                        label: "Запуск main.py".into(),
                        enabled: !has_docker,
                        action_type: ActionType::RunCommand {
                            command: "python main.py".into(), 
                            working_dir: Some(current_working_dir.to_string())
                            }
                    };
                    launch_actions.push(py_action2);
                    is_python_project = true;
                }
                "manage.py" => {
                    let django_action = LaunchAction {
                        id: generate_id(),
                        label: "Запуск локального сервера Django".into(),
                        enabled: true,
                        action_type: ActionType::RunCommand {
                            command: "python manage.py runserver".into(), 
                            working_dir: Some(current_working_dir.to_string())
                            }
                    };
                    launch_actions.push(django_action);


                    let django_action2 = LaunchAction {
                        id: generate_id(),
                        label: "Запуск миграции базы данных (Django)".into(),
                        enabled: true,
                        action_type: ActionType::RunCommand {
                            command: "python manage.py migrate".into(), 
                            working_dir: Some(current_working_dir.to_string())
                            }
                    };
                    launch_actions.push(django_action2);
                    is_python_project = true;
                }
                "build.gradle" | "build.gradle.kts" => {
                    let content = fs::read_to_string(&path).unwrap_or_default();

                    // Проверяем, содержит ли файл упоминание Spring Boot
                    let is_spring = content.contains("org.springframework.boot") || content.contains("spring-boot");

                    // Выбираем команду на основе анализа текста
                    let gradle_command = if is_spring {
                        "./gradlew bootRun"
                    } else {
                        "./gradlew run"
                    };

                    let gradle_action = LaunchAction {
                        id: generate_id(),
                        label: format!("Запустить Gradle ({})", gradle_command).into(),
                        enabled: true,
                        action_type: ActionType::RunCommand {
                            command: gradle_command.into(),
                            working_dir: Some(current_working_dir.to_string()),
                        },
                    };
                    launch_actions.push(gradle_action);
                }
                "pom.xml" => {
                    let content = fs::read_to_string(&path).unwrap_or_default();

                    let is_spring = content.contains("spring-boot");
                    let java_command = if is_spring {"mvn spring-boot:run"} else {"mvn exec:java"};

                    let java_action = LaunchAction {
                        id: generate_id(),
                        label: format!("Запустить Java (сборщик Maven) ({})", java_command).into(),
                        enabled: true,
                        action_type: ActionType::RunCommand {
                            command: java_command.into(),
                            working_dir: Some(current_working_dir.to_string()),
                        },
                    };
                    launch_actions.push(java_action);
                }
                "Gemfile" => {
                    let ruby_action = LaunchAction {
                        id: generate_id(),
                        label: "Запустить Rails веб-проект".into(),
                        enabled: true,
                        action_type: ActionType::RunCommand {
                            command: "bundle exec rails server".into(),
                            working_dir: Some(current_working_dir.to_string()),
                        },
                    };

                    launch_actions.push(ruby_action);

                    let port_action = LaunchAction {
                        id: generate_id(),
                        label: "Ожидание веб-порта для Rails".into(),
                        enabled: true,
                        action_type: ActionType::WaitForPort {
                            host: "127.0.0.1".into(),
                            port: 3000,
                            timeout_secs: 15,
                        },
                    };
                    launch_actions.push(port_action);
                }
                "index.html" => {has_index_html = true;}
                _ => {
                    if filename.ends_with(".csproj") {
                        let cs_action = LaunchAction {
                                id: generate_id(),
                                label: "Запустить C# (.NET)".into(),
                                enabled: true,
                                action_type: ActionType::RunCommand {
                                    command: "dotnet run".into(),
                                    working_dir: Some(current_working_dir.to_string()),
                                },
                            };

                        launch_actions.push(cs_action);

                        let cs_action2 = LaunchAction {
                            id: generate_id(),
                                label: "Запуск режима горячей перезагрузки для .NET".into(),
                                enabled: true,
                                action_type: ActionType::RunCommand {
                                    command: "dotnet watch".into(),
                                    working_dir: Some(current_working_dir.to_string()),
                                },
                            };    
                        launch_actions.push(cs_action2);
                    }
                }
            }

        }

        if launch_actions.is_empty() && has_index_html {
            let action = LaunchAction {
                    id: generate_id(),
                        label: "Открытие index.html в браузере".into(),
                        enabled: true,
                        action_type: ActionType::OpenUrl {
                            url: index_html_sys_path,
                        },
                    };    
                launch_actions.push(action);
        }

        let (ide_name, ide_label) = if is_python_project {
            ("pycharm", "Открыть в PyCharm")
        } else {
            ("code", "Открыть в VS Code")
        };

        if which::which(ide_name).is_ok() {
            let ide_action = LaunchAction {
                id: generate_id(),
                label: ide_label.into(),
                enabled: true,
                action_type: ActionType::OpenApplication {
                    path: ide_name.into(),
                    args: Some(".".into()),
                },
            };
            launch_actions.push(ide_action);
        } else if ide_name == "pycharm" && which::which("code").is_ok() {
            // Если проект питоновский, но PyCharm не установлен, а VS Code есть — предлагаем открыть в VS Code
            let fallback_action = LaunchAction {
                id: generate_id(),
                label: "Открыть в VS Code (PyCharm не найден)".into(),
                enabled: true,
                action_type: ActionType::OpenApplication {
                    path: "code".into(),
                    args: Some(".".into()),
                },
            };
            launch_actions.push(fallback_action);
        }

        let project_name = Path::new(project_path)
        .file_name()
        .and_then(|os_str| os_str.to_str())
        .unwrap_or("Проанализированный проект");

        Ok(LaunchProfile {
            name: format!("Проект {}", project_name),
            description: format!("Автоматически найденный профиль для {}", project_path),
            project_path: Some(project_path.to_string()),
            actions: launch_actions
        })
    }

}

fn generate_id() -> String {
    use std::time::{SystemTime, UNIX_EPOCH};
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos();
    format!("act_{}", nanos)
}

