    Killed,
    Crashed,
}

struct ActiveProcess {
    info: TrackedProcess,
    child: Option<Child>,
}

use std::process::{Command, Stdio};


pub trait ProcessManager: Send + Sync {
    fn spawn_and_track(&self, cmd: &str, args: &[&str], working_dir: Option<&str>, label: &str) -> Result<TrackedProcess, String>;
    // Получить список всех процессов
    fn list(&self) -> Vec<TrackedProcess>;

    // Убить процесс по ID
    fn kill(&self, id: &str) -> Result<(), String>;

    // Обновить статус конкретного процесса
    fn refresh_status(&self, id: &str) -> Result<ProcessStatus, String>;
}

pub struct OsProcessManager {
    // Потокобезопасная таблица: Ключ — ID процесса, Значение — данные + Child
    processes: Arc<Mutex<HashMap<String, ActiveProcess>>>,
}

impl OsProcessManager {
    // Конструктор для создания монитора при старте приложения
    pub fn new() -> Self {
        Self {
            processes: Arc::new(Mutex::new(HashMap::new())),
        }
    }
}

fn generate_id() -> String {
    use std::time::{SystemTime, UNIX_EPOCH};
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos();
    format!("act_{}", nanos)
}
impl ProcessManager for OsProcessManager {
    fn spawn_and_track(&self, command: &str, args: &[&str], working_dir: Option<&str>, label: &str) -> Result<TrackedProcess, String> {
        let mut cmd = Command::new("cmd");
        cmd.arg("/C").arg(command).args(args)
            .stdout(Stdio::null())
            .stderr(Stdio::null());
        if let Some(dir) = working_dir {
            cmd.current_dir(dir);
        }

        let child = cmd.spawn().map_err(|e| format!("Ошибка запуска: {}", e))?;
        let pid = child.id();
        let my_id = generate_id();
        let started_at = chrono::Local::now().format("%d.%m.%Y %H:%M:%S").to_string();

        let info = TrackedProcess {
            id: my_id.clone(),
            pid,
            label: label.to_string(),
            status: ProcessStatus::Running,
            started_at,
        };

        let active_process = ActiveProcess {
            info: info.clone(),
            child: Some(child),
        };

        // Блокируем мутекс, чтобы безопасно вставить данные в HashMap
        let mut lock = self.processes.lock().unwrap();
        lock.insert(my_id, active_process);

        Ok(info)


    }
    fn list(&self) -> Vec<TrackedProcess> {
        let lock = self.processes.lock().unwrap();
        let processes = lock.values();
        let mut process_list: Vec<TrackedProcess> = Vec::new();

        for process in processes {
            let result = process.info.clone();
            process_list.push(result);
        }
        return process_list;
    }

    fn kill(&self, id: &str) -> Result<(), String> {
        let mut lock = self.processes.lock().unwrap();

        if let Some(process) = lock.get_mut(id) {
            let pid = process.info.pid;

            let pid_str = pid.to_string();
            let _ = Command::new("taskkill")
                .args(["/F", "/PID", &pid_str])
                .status();

            process.child = None;
            process.info.status = ProcessStatus::Killed;

            Ok(()) 
        } else {
            Err(format!("Процесс с id {} не найден", id))
        }     
    }

    fn refresh_status(&self, id: &str) -> Result<ProcessStatus, String> {
        let mut lock = self.processes.lock().unwrap();

        if let Some(process) = lock.get_mut(id) {
            if let Some(ref mut child_proc) = process.child {
                match child_proc.try_wait() {
                    Ok(None) => {
                        // Процесс все еще работает!
                        process.info.status = ProcessStatus::Running;
                        Ok(ProcessStatus::Running)
                    }
                    Ok(Some(status)) => {
                        process.child = None;


                        let exit_code = status.code().unwrap_or(-1);

                        let new_status = if status.success() {
                            ProcessStatus::Exited(exit_code)
                        } else {
                            ProcessStatus::Crashed
                        };

                        process.info.status = new_status.clone();

                        Ok(new_status) 
                    }
                    Err(e) => Err(format!("Ошибка ОС при вызове try_wait: {}", e)),
                }
            } else {
                Ok(process.info.status.clone())
            }
        } else {
            Err(format!("Процесс с id {} не найден", id))
        }      
    }
}

