pub mod models;
pub mod settings;
pub mod process_manager;

use serde::{Deserialize, Serialize};

// ===== AppSettings (глобальные настройки StackPilot) =====

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PreferredApp {
    pub name: String,
    pub path: String,
    pub args: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AppSettings {
    pub vscode_path: String,
    pub browser_path: String,
    pub terminal: String,
    pub theme: String,
    pub language: String,
    pub auto_save_profiles: bool,
    pub preferred_apps: Vec<PreferredApp>,
}

// ===== TrackedProcess (процессы, используемые всеми модулями) =====

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TrackedProcess {
    pub id: String,
    pub pid: u32,
    pub label: String,
    pub status: ProcessStatus,
    pub started_at: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum ProcessStatus {
    Running,
    Exited(i32),
    Killed,
    Crashed,
}

use std::path::PathBuf;
use std::fs;
use std::sync::Arc;
use tauri::State;

use crate::core::models::*;

pub trait SettingsService: Send + Sync {
    fn get_settings(&self) -> Result<AppSettings, String>;
    fn update_settings(&self, settings: &AppSettings) -> Result<(), String>;
    fn reset_to_defaults(&self) -> Result<AppSettings, String>;
}

pub struct JsonSettingsService {
    settings_path: PathBuf,
}

impl JsonSettingsService {
    pub fn new(app_data_dir: PathBuf) -> Self {
        Self {
            settings_path: app_data_dir.join("settings.json"),
        }
    }

    fn load(&self) -> Result<AppSettings, String> {
        let content = fs::read_to_string(&self.settings_path)
            .map_err(|e| format!("Failed to read settings: {}", e))?;
        serde_json::from_str(&content)
            .map_err(|e| format!("Failed to parse settings: {}", e))
    }

    fn save(&self, settings: &AppSettings) -> Result<(), String> {
        let content = serde_json::to_string_pretty(settings)
            .map_err(|e| format!("Failed to serialize settings: {}", e))?;
        fs::write(&self.settings_path, content)
            .map_err(|e| format!("Failed to write settings: {}", e))
    }

    fn defaults() -> AppSettings {
        AppSettings {
            vscode_path: "code".into(),
            browser_path: String::new(),
            terminal: String::new(),
            theme: "system".into(),
            language: "ru".into(),
            auto_save_profiles: true,
            preferred_apps: vec![
                PreferredApp {
                    name: "VS Code".into(),
                    path: "code".into(),
                    args: None,
                },
            ],
        }
    }
}

impl SettingsService for JsonSettingsService {
    fn get_settings(&self) -> Result<AppSettings, String> {
        if !self.settings_path.exists() {
            let defaults = Self::defaults();
            self.save(&defaults)?;
            return Ok(defaults);
        }
        self.load()
    }

    fn update_settings(&self, settings: &AppSettings) -> Result<(), String> {
        self.save(settings)
    }

    fn reset_to_defaults(&self) -> Result<AppSettings, String> {
        let defaults = Self::defaults();
        self.save(&defaults)?;
        Ok(defaults)
    }
}

// ===== State wrapper + Tauri commands =====

/// Обёртка для регистрации в Tauri State
pub struct SettingsState(pub Arc<dyn SettingsService>);

#[tauri::command]
pub fn get_settings(state: State<'_, SettingsState>) -> Result<AppSettings, String> {
    state.0.get_settings()
}

#[tauri::command]
pub fn update_settings(state: State<'_, SettingsState>, settings: AppSettings) -> Result<(), String> {
    state.0.update_settings(&settings)
}

#[tauri::command]
pub fn reset_settings(state: State<'_, SettingsState>) -> Result<AppSettings, String> {
    state.0.reset_to_defaults()
}

use std::collections::HashMap;
use std::process::{Child, Command, Stdio};
use std::sync::{Arc, Mutex};
use std::time::{SystemTime, UNIX_EPOCH};

use crate::core::models::*;

// ===== Внутреннее хранение =====

struct ActiveProcess {
    info: TrackedProcess,
    child: Option<Child>,
}

// ===== Трейт =====

pub trait ProcessManager: Send + Sync {
    fn spawn_and_track(
        &self,
        command: &str,
        args: &[String],
        working_dir: Option<&str>,
        label: &str,
    ) -> Result<TrackedProcess, String>;

    fn list(&self) -> Vec<TrackedProcess>;
    fn kill(&self, id: &str) -> Result<(), String>;
    fn refresh_status(&self, id: &str) -> Result<ProcessStatus, String>;
}

// ===== Реализация =====

pub struct OsProcessManager {
    processes: Arc<Mutex<HashMap<String, ActiveProcess>>>,
}

impl OsProcessManager {
    pub fn new() -> Self {
        Self {
            processes: Arc::new(Mutex::new(HashMap::new())),
        }
    }
}

impl ProcessManager for OsProcessManager {
    fn spawn_and_track(
        &self,
        command: &str,
        args: &[String],
        working_dir: Option<&str>,
        label: &str,
    ) -> Result<TrackedProcess, String> {
        let mut cmd = Command::new("cmd");
        cmd.arg("/C")
            .arg(command)
            .args(args)
            .stdout(Stdio::null())
            .stderr(Stdio::null());

        if let Some(dir) = working_dir {
            cmd.current_dir(dir);
        }

        let child = cmd.spawn().map_err(|e| format!("Spawn failed: {}", e))?;
        let pid = child.id();
        let id = generate_id();
        let started_at = timestamp_now();

        let info = TrackedProcess {
            id: id.clone(),
            pid,
            label: label.to_string(),
            status: ProcessStatus::Running,
            started_at,
        };

        let entry = ActiveProcess {
            info: info.clone(),
            child: Some(child),
        };

        self.processes
            .lock()
            .expect("processes lock poisoned")
            .insert(id, entry);

        Ok(info)
    }

    fn list(&self) -> Vec<TrackedProcess> {
        let lock = self.processes.lock().expect("processes lock poisoned");
        lock.values().map(|p| p.info.clone()).collect()
    }

    fn kill(&self, id: &str) -> Result<(), String> {
        let mut lock = self.processes.lock().expect("processes lock poisoned");
        let entry = lock
            .get_mut(id)
            .ok_or_else(|| format!("Process '{}' not found", id))?;

        let _ = Command::new("taskkill")
            .args(["/F", "/PID", &entry.info.pid.to_string()])
            .status();

        entry.child = None;
        entry.info.status = ProcessStatus::Killed;
        Ok(())
    }

    fn refresh_status(&self, id: &str) -> Result<ProcessStatus, String> {
        let mut lock = self.processes.lock().expect("processes lock poisoned");
        let entry = lock
            .get_mut(id)
            .ok_or_else(|| format!("Process '{}' not found", id))?;

        if let Some(ref mut child) = entry.child {
            match child.try_wait() {
                Ok(None) => {
                    entry.info.status = ProcessStatus::Running;
                    Ok(ProcessStatus::Running)
                }
                Ok(Some(status)) => {
                    entry.child = None;
                    let new_status = if status.success() {
                        ProcessStatus::Exited(status.code().unwrap_or(0))
                    } else {
                        ProcessStatus::Crashed
                    };
                    entry.info.status = new_status.clone();
                    Ok(new_status)
                }
                Err(e) => Err(format!("try_wait error: {}", e)),
            }
        } else {
            Ok(entry.info.status.clone())
        }
    }
}

fn generate_id() -> String {
    let nanos = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_nanos();
    format!("proc_{}", nanos)
}

fn timestamp_now() -> String {
    let dur = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default();
    dur.as_secs().to_string()
}

