use std::path::PathBuf;
use std::fs;
use crate::modules::devlauncher::models::*;

pub trait ProfileManager: Send + Sync {
    fn list_profiles(&self) -> Result<Vec<LaunchProfile>, String>;
    fn get_profile(&self, name: &str) -> Result<LaunchProfile, String>;
    fn save_profile(&self, profile: &LaunchProfile) -> Result<(), String>;
    fn delete_profile(&self, name: &str) -> Result<(), String>;
}

pub struct JsonProfileManager {
    profiles_dir: PathBuf,
}

impl JsonProfileManager {
    pub fn new(profiles_dir: PathBuf) -> Self {
        Self { profiles_dir }
    }

    fn profile_path(&self, name: &str) -> PathBuf {
        self.profiles_dir.join(format!("{}.json", name))
    }
}

impl ProfileManager for JsonProfileManager {
    fn list_profiles(&self) -> Result<Vec<LaunchProfile>, String> {
        let mut profiles = Vec::new();
        let entries = fs::read_dir(&self.profiles_dir)
            .map_err(|e| format!("Failed to read profiles dir: {}", e))?;

        for entry in entries {
            let entry = entry.map_err(|e| format!("Failed to read entry: {}", e))?;
            let path = entry.path();
            if path.extension().map_or(false, |ext| ext == "json") {
                let content = fs::read_to_string(&path)
                    .map_err(|e| format!("Failed to read {}: {}", path.display(), e))?;
                let profile: LaunchProfile = serde_json::from_str(&content)
                    .map_err(|e| format!("Failed to parse {}: {}", path.display(), e))?;
                profiles.push(profile);
            }
        }
        Ok(profiles)
    }

    fn get_profile(&self, name: &str) -> Result<LaunchProfile, String> {
        let path = self.profile_path(name);
        let content = fs::read_to_string(&path)
            .map_err(|e| format!("Failed to read profile '{}': {}", name, e))?;
        serde_json::from_str(&content)
            .map_err(|e| format!("Failed to parse profile '{}': {}", name, e))
    }

    fn save_profile(&self, profile: &LaunchProfile) -> Result<(), String> {
        let path = self.profile_path(&profile.name);
        let content = serde_json::to_string_pretty(profile)
            .map_err(|e| format!("Failed to serialize profile: {}", e))?;
        fs::write(&path, content)
            .map_err(|e| format!("Failed to write profile '{}': {}", profile.name, e))
    }

    fn delete_profile(&self, name: &str) -> Result<(), String> {
        let path = self.profile_path(name);
        fs::remove_file(&path)
            .map_err(|e| format!("Failed to delete profile '{}': {}", name, e))
    }
}

use std::time::Duration;
use std::process::{Command, Stdio};
use std::thread;
use std::net::{TcpStream, ToSocketAddrs};
use std::io::{Write, BufReader, BufRead};
use crate::modules::devlauncher::models::*;

pub trait LaunchEngine: Send + Sync {
    fn execute_action(&self, action: &LaunchAction) -> Result<ActionStatus, String>;
}

pub struct ProcessLaunchEngine;

impl LaunchEngine for ProcessLaunchEngine {
    fn execute_action(&self, action: &LaunchAction) -> Result<ActionStatus, String> {
        if !action.enabled {
            return Ok(ActionStatus::Skipped {
                reason: format!("Action '{}' disabled", action.label),
            });
        }

        match &action.action_type {
            ActionType::RunCommand { command, working_dir } => {
                let mut cmd = Command::new("cmd");
                cmd.arg("/C").arg(command)
                    .stdout(Stdio::null())
                    .stderr(Stdio::null());
                if let Some(dir) = working_dir {
                    cmd.current_dir(dir);
                }
                match cmd.spawn() {
                    Ok(_) => Ok(ActionStatus::Success {
                        message: format!("Command started: {}", command),
                    }),
                    Err(e) => Err(format!("Failed to start process: {}", e)),
                }
            }

            ActionType::OpenUrl { url } => {
                match webbrowser::open(url) {
                    Ok(_) => Ok(ActionStatus::Success {
                        message: format!("Browser opened: {}", url),
                    }),
                    Err(e) => Err(format!("Failed to open browser: {}", e)),
                }
            }

            ActionType::OpenApplication { path, args } => {
                let mut cmd = Command::new(path);
                cmd.stdout(Stdio::null()).stderr(Stdio::null());
                if let Some(args_str) = args {
                    cmd.args(args_str.split_whitespace());
                }
                match cmd.spawn() {
                    Ok(_) => Ok(ActionStatus::Success {
                        message: format!("App launched: {}", path),
                    }),
                    Err(e) => Err(format!("Failed to launch app: {}", e)),
                }
            }

            ActionType::WaitForUrl { url, timeout_secs } => {
                let parsed = parse_http_url(url)?;
                let addr_str = format!("{}:{}", parsed.host, parsed.port);
                let addrs = addr_str
                    .to_socket_addrs()
                    .map_err(|e| format!("DNS resolve failed: {}", e))?
                    .collect::<Vec<_>>();

                for _ in 0..*timeout_secs {
                    for addr in &addrs {
                        if let Ok(mut stream) = TcpStream::connect_timeout(addr, Duration::from_secs(2)) {
                            let request = format!(
                                "GET {} HTTP/1.1\r\nHost: {}\r\nConnection: close\r\n\r\n",
                                parsed.path, parsed.host
                            );
                            if stream.write_all(request.as_bytes()).is_err() { continue; }
                            let mut reader = BufReader::new(&stream);
                            let mut first_line = String::new();
                            if reader.read_line(&mut first_line).is_err() { continue; }

                            let parts: Vec<&str> = first_line.split_whitespace().collect();
                            if let Some(code_str) = parts.get(1) {
                                if let Ok(code) = code_str.parse::<u16>() {
                                    if (200..400).contains(&code) {
                                        return Ok(ActionStatus::Success {
                                            message: format!("URL {} responded with {}", url, code),
                                        });
                                    }
                                }
                            }
                        }
                    }
                    thread::sleep(Duration::from_secs(1));
                }
                Err(format!("Timeout: {} not available after {}s", url, timeout_secs))
            }

            ActionType::WaitForPort { host, port, timeout_secs } => {
                let addr_str = format!("{}:{}", host, port);
                let addrs = addr_str
                    .to_socket_addrs()
                    .map_err(|e| format!("DNS resolve failed: {}", e))?
                    .collect::<Vec<_>>();

                for _ in 0..*timeout_secs {
                    for addr in &addrs {
                        if TcpStream::connect_timeout(addr, Duration::from_secs(1)).is_ok() {
                            return Ok(ActionStatus::Success {
                                message: format!("Port {}:{} is open", host, port),
                            });
                        }
                    }
                    thread::sleep(Duration::from_secs(1));
                }
                Err(format!("Timeout: port {}:{} not open after {}s", host, port, timeout_secs))
            }

            ActionType::Delay { seconds } => {
                thread::sleep(Duration::from_secs(*seconds));
                Ok(ActionStatus::Success {
                    message: format!("Delay {}s completed", seconds),
                })
            }

            ActionType::ExecuteScript { script, shell } => {
                let shell_name = shell.as_deref().unwrap_or("cmd");
                let flag = match shell_name {
                    "cmd" => "/C",
                    "powershell" | "pwsh" => "-Command",
                    _ => "-c",
                };
                let exit = Command::new(shell_name)
                    .args([flag, script])
                    .stdout(Stdio::null())
                    .stderr(Stdio::null())
                    .status()
                    .map_err(|e| format!("Failed to run shell '{}': {}", shell_name, e))?;

                if exit.success() {
                    Ok(ActionStatus::Success {
                        message: format!("Script executed: {}", script),
                    })
                } else {
                    let code = exit.code().unwrap_or(-1);
                    Ok(ActionStatus::Failed {
                        error: format!("Script exited with code {}", code),
                    })
                }
            }
        }
    }
}

struct ParsedUrl {
    host: String,
    port: u16,
    path: String,
}

fn parse_http_url(raw: &str) -> Result<ParsedUrl, String> {
    let without_proto = raw
        .strip_prefix("http://")
        .or_else(|| raw.strip_prefix("https://"))
        .unwrap_or(raw);
    let (host_port, path) = match without_proto.split_once('/') {
        Some((hp, p)) => (hp, format!("/{}", p)),
        None => (without_proto, "/".to_string()),
    };
    let (host, port) = match host_port.split_once(':') {
        Some((h, p)) => (
            h.to_string(),
            p.parse::<u16>().map_err(|_| format!("Invalid port in URL: {}", raw))?,
        ),
        None => (host_port.to_string(), 80),
    };
    Ok(ParsedUrl { host, port, path })
}

use std::fs;
use std::path::Path;
use walkdir::WalkDir;
use crate::modules::devlauncher::models::*;

pub trait ProjectAnalyzer: Send + Sync {
    fn analyze(&self, project_path: &str) -> Result<LaunchProfile, String>;
}

pub struct FsProjectAnalyzer;

impl ProjectAnalyzer for FsProjectAnalyzer {
    fn analyze(&self, project_path: &str) -> Result<LaunchProfile, String> {
        let mut launch_actions: Vec<LaunchAction> = Vec::new();
        let walker = WalkDir::new(project_path).follow_links(false).into_iter();
        let mut it = walker;

        let mut has_docker = false;
        let mut has_dockerfile = false;
        let mut has_index_html = false;
        let mut index_html_path = String::new();
        let mut has_python_project = false;
        let mut has_go_project = false;
        let mut has_makefile = false;
        let mut has_sln = false;
        let port_re = regex::Regex::new(r"--port\s+(\d+)").unwrap();

        while let Some(entry_result) = it.next() {
            let entry = match entry_result {
                Ok(e) => e,
                Err(err) => {
                    println!("[Analyzer] Access error: {}", err);
                    continue;
                }
            };

            let path = entry.path();
            let filename = path.file_name().and_then(|n| n.to_str()).unwrap_or("");

            if entry.file_type().is_dir() {
                if matches!(filename, "node_modules" | ".git" | "target" | ".venv" | "__pycache__" | ".next") {
                    it.skip_current_dir();
                    continue;
                }
            }

            let cwd = path.parent()
                .and_then(|p| p.to_str())
                .unwrap_or(project_path)
                .to_string();

            match filename {
                "docker-compose.yml" | "docker-compose.yaml" => {
                    launch_actions.push(LaunchAction {
                        id: generate_id(),
                        label: "Start Docker Compose".into(),
                        enabled: true,
                        action_type: ActionType::RunCommand {
                            command: "docker compose up -d".into(),
                            working_dir: Some(cwd.clone()),
                        },
                    });
                    has_docker = true;
                }
                _ => {}
            }

            if filename == "Dockerfile" && !has_dockerfile {
                has_dockerfile = true;
                launch_actions.push(LaunchAction {
                    id: generate_id(),
                    label: "Build Docker image".into(),
                    enabled: !has_docker,
                    action_type: ActionType::RunCommand {
                        command: "docker build -t myapp .".into(),
                        working_dir: Some(cwd.clone()),
                    },
                });
                launch_actions.push(LaunchAction {
                    id: generate_id(),
                    label: "Run Docker container".into(),
                    enabled: !has_docker,
                    action_type: ActionType::RunCommand {
                        command: "docker run -p 8080:80 myapp".into(),
                        working_dir: Some(cwd.clone()),
                    },
                });
                has_docker = true;
            }

            if filename == "package.json" {
                let content = fs::read_to_string(path)
                    .map_err(|e| format!("Failed to read package.json: {}", e))?;
                let value: serde_json::Value = serde_json::from_str(&content)
                    .map_err(|e| format!("Failed to parse package.json: {}", e))?;

                let scripts = value.get("scripts");
                let deps = value.get("dependencies");
                let dev_deps = value.get("devDependencies");
                let has_dep = |pkg: &str| {
                    deps.and_then(|d| d.get(pkg)).is_some()
                        || dev_deps.and_then(|d| d.get(pkg)).is_some()
                };

                let run_cmd = if has_dep("expo") {
                    "npx expo start".to_string()
                } else if has_dep("@nestjs/core") {
                    scripts.and_then(|s| s.get("start:dev"))
                        .and_then(|c| c.as_str())
                        .unwrap_or("npm run start:dev")
                        .to_string()
                } else {
                    let chosen = scripts
                        .and_then(|s| s.get("dev").or_else(|| s.get("start")))
                        .and_then(|c| c.as_str())
                        .unwrap_or("dev");
                    format!("npm run {}", chosen)
                };

                let mut port: u16 = 3000;
                if let Some(caps) = port_re.captures(&run_cmd) {
                    if let Ok(p) = caps[1].parse() { port = p; }
                }

                launch_actions.push(LaunchAction {
                    id: generate_id(),
                    label: "Run Node.js project".into(),
                    enabled: true,
                    action_type: ActionType::RunCommand {
                        command: run_cmd,
                        working_dir: Some(cwd.clone()),
                    },
                });

                if !has_dep("expo") {
                    launch_actions.push(LaunchAction {
                        id: generate_id(),
                        label: "Wait for Node.js port".into(),
                        enabled: true,
                        action_type: ActionType::WaitForPort {
                            host: "127.0.0.1".into(),
                            port,
                            timeout_secs: 30,
                        },
                    });
                }
            }

            if filename == "Cargo.toml" {
                let content = fs::read_to_string(path)
                    .map_err(|e| format!("Failed to read Cargo.toml: {}", e))?;
                let value: toml::Value = toml::from_str(&content)
                    .map_err(|e| format!("Failed to parse Cargo.toml: {}", e))?;
                if value.get("workspace").is_some() { continue; }

                let has_tauri = value.get("dependencies").and_then(|d| d.get("tauri")).is_some();
                let cmd = if has_tauri { "cargo tauri dev" } else { "cargo run" };
                let port = if has_tauri { 1420 } else { 3000 };

                launch_actions.push(LaunchAction {
                    id: generate_id(),
                    label: "Run Rust project".into(),
                    enabled: !has_docker,
                    action_type: ActionType::RunCommand {
                        command: cmd.into(),
                        working_dir: Some(cwd.clone()),
                    },
                });
                if has_tauri {
                    launch_actions.push(LaunchAction {
                        id: generate_id(),
                        label: "Wait for Tauri port".into(),
                        enabled: true,
                        action_type: ActionType::WaitForPort {
                            host: "127.0.0.1".into(),
                            port,
                            timeout_secs: 60,
                        },
                    });
                }
            }

            if (filename == "go.mod" || filename == "main.go") && !has_go_project {
                has_go_project = true;
                launch_actions.push(LaunchAction {
                    id: generate_id(),
                    label: "Run Go project".into(),
                    enabled: !has_docker,
                    action_type: ActionType::RunCommand {
                        command: "go run .".into(),
                        working_dir: Some(cwd.clone()),
                    },
                });
            }

            if filename == "requirements.txt" {
                launch_actions.push(LaunchAction {
                    id: generate_id(),
                    label: "Install Python deps".into(),
                    enabled: !has_docker,
                    action_type: ActionType::RunCommand {
                        command: "pip install -r requirements.txt".into(),
                        working_dir: Some(cwd.clone()),
                    },
                });
                has_python_project = true;
            }

            if filename == "pyproject.toml" {
                launch_actions.push(LaunchAction {
                    id: generate_id(),
                    label: "Install Python deps (pyproject)".into(),
                    enabled: !has_docker,
                    action_type: ActionType::RunCommand {
                        command: "pip install -e .".into(),
                        working_dir: Some(cwd.clone()),
                    },
                });
                has_python_project = true;
            }

            if filename == "main.py" {
                launch_actions.push(LaunchAction {
                    id: generate_id(),
                    label: "Run main.py".into(),
                    enabled: !has_docker,
                    action_type: ActionType::RunCommand {
                        command: "python main.py".into(),
                        working_dir: Some(cwd.clone()),
                    },
                });
                has_python_project = true;
            }

            if filename == "manage.py" {
                launch_actions.push(LaunchAction {
                    id: generate_id(),
                    label: "Run Django server".into(),
                    enabled: true,
                    action_type: ActionType::RunCommand {
                        command: "python manage.py runserver".into(),
                        working_dir: Some(cwd.clone()),
                    },
                });
                launch_actions.push(LaunchAction {
