async function loadProfile() {
  loading = true;
  errorMsg = "";
  const name = profileName;

  if (!name) {
    errorMsg = "Profile name not specified";
    loading = false;
    return;
  }

  try {
    const demo = await getDemoProfile();
    if (demo.name === name) {
      profile = demo;
    } else {
      profile = await getProfile(name);
    }
  } catch (e) {
    errorMsg = `Не удалось загрузить профиль "${name}": ${e}`;
  }

  loading = false;
}

